#!/usr/bin/env bash
#
# supabase-vps-setup — walks Justin through the four human-only setup steps for
# Kinetic Lists v1: the GitHub OAuth App, the hosted Supabase project's auth
# config, the VPS runtime, and the deploy secrets.
#
# Generated by the /wizard skill (.agents/skills/wizard/SKILL.md). Library above
# the STAGES marker is the shared wizard library: do not hand-edit it.
#
# Read the rules first (Stage 1). This wizard never provisions: nginx, certbot,
# Node and pnpm already exist on the box, and it only probes them. It never runs
# `supabase db reset`, `supabase db push` or `supabase config push`, and it never
# touches a secret value it can see — the OAuth client secret is pasted by hand
# into Studio, and lives nowhere in this repo.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub Actions secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub Actions secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub Actions secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub Actions variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub Actions variable $name")
  warn "skipped GitHub Actions variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub Actions secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Map facts this wizard walks. Keeping them here means the runbook and the run
# never drift apart.
HOSTED_REF="ohbrawtgcyngyhaqtddy"
HOSTED_URL="https://${HOSTED_REF}.supabase.co"
ORIGIN="https://kinetic-lists.justintaddei.com"
CALLBACK="${HOSTED_URL}/auth/v1/callback"
EXPECTED_MIGRATIONS="20261030005109 20261031000000 20261101000000 20261103000000"
KEY_DIR="${KEY_DIR:-.secrets}"

run_wizard() {

TOTAL_STAGES=9

banner "Kinetic Lists · hosted Supabase + VPS setup"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "The four steps, and what this wizard will not do"
say "Human-only setup, in order: the GitHub OAuth App, the hosted project's"
say "auth config, the VPS runtime, the deploy secrets. Measured 2026-11-02:"
note "· GitHub sign-in is ALREADY enabled on ${HOSTED_REF} (Settings → Auth → Providers)."
note "· Migration history is clean on hosted and local (${EXPECTED_MIGRATIONS}): nothing queued."
note "· The client secret is pasted by hand into Studio, so it never enters this repo."
note "· No geocoder and no map key exist in v1 (ADR-0013, #15), so there is no key step here."
warn "This wizard never provisions. nginx + certbot + Node 20.19.1+ + pnpm 10.20.0 exist"
warn "on the box already; it probes them and stops if a probe fails."
warn "It never runs: supabase db reset · supabase db push · supabase config push."
warn "Hosted history is append-only, the box is production, and config push would"
warn "overwrite hosted config from supabase/config.toml. Confirm you have read this."
if ! confirm "Read the four rules above?"; then
  say "Stop here, read docs/runbooks/supabase-vps-setup.md, then re-run."
  exit 1
fi

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Local dev sign-in (ADR-0008)"
say "Hosted sign-in is GitHub-only. The local stack is the only place email sign-in"
say "exists, and ADR-0008 fixes the account: GoTrue derives the email from the"
say "password's local part — sha256 as hex, plus a literal @example.com suffix."
step "Start the local stack if it is down: pnpm exec supabase start"
step "Local service-role key: pnpm exec supabase status -o env  (SERVICE_ROLE_KEY)"
ask DEV_LOGIN_LOCAL_PART "Local part of the dev account (e.g. tester)"
ask_secret DEV_LOGIN_PASSWORD "Dev account password (its local part is the hashed half)"
ask_secret DEV_LOGIN_SERVICE_ROLE_KEY "Local SERVICE_ROLE_KEY"
if [[ "$DEV_LOGIN_PASSWORD" != "$DEV_LOGIN_LOCAL_PART"* ]]; then
  warn "ADR-0008 hashes the LOCAL PART of the password you sign in with."
  warn "Keep the password's local part equal to the value above, or the email will not match."
fi
hex=$(printf '%s' "$DEV_LOGIN_LOCAL_PART" | sha256sum | cut -c1-40)
write_env DEV_LOGIN_EMAIL "${hex}@example.com"
write_env DEV_LOGIN_PASSWORD "$DEV_LOGIN_PASSWORD"
write_env DEV_LOGIN_SERVICE_ROLE_KEY "$DEV_LOGIN_SERVICE_ROLE_KEY"
note "fixture email = ${hex}@example.com (the derived address; the password is what you type)"
say "Prove the fixture exists on the local stack:"
say "   curl -sS -X POST http://127.0.0.1:54321/auth/v1/admin/users \\"
say "     -H 'apikey: <SERVICE_ROLE_KEY>' -H 'authorization: Bearer <SERVICE_ROLE_KEY>' \\"
say "     -H 'content-type: application/json' \\"
say "     -d '{\"email\":\"${hex}@example.com\",\"password\":\"${DEV_LOGIN_LOCAL_PART}\",\"email_confirm\":true}'"
note "a 200 (or a 422 naming an existing email) is success; a connection refused means local Auth is down."
if confirm "The fixture user is listed at Studio (local stack) → Authentication → Users?"; then
  note "fixture ready; hosted keeps GitHub only"
else
  warn "The dev sign-in card itself is #27's deliverable (app code, dev-gated); the"
  warn "two shapes are recorded in #27's comments. This wizard mints the account + the .env trio."
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "GitHub OAuth App"
say "One OAuth App on your personal account. Everything you type here is public:"
say "GitHub shows the app name to strangers, so no private URLs in the name."
open_url "https://github.com/settings/applications/new"
step "Application name: Kinetic Lists"
step "Homepage URL: ${ORIGIN}"
step "Authorization callback URL: ${CALLBACK}"
step "Do NOT tick 'Enable Device Flow'"
ask_secret GITHUB_OAUTH_CLIENT_ID "Client ID (copy from the app page)"
note "This App's Client Secret is asked for in the next stage, on Supabase's dashboard."
note "It never passes through this wizard, .env, or a GitHub Actions secret:"
note "GoTrue exchanges the code server-side, on the hosted project."
write_env NUXT_PUBLIC_GITHUB_CLIENT_ID "$GITHUB_OAUTH_CLIENT_ID"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Hosted project: provider credentials, Site URL, Redirect URLs"
say "Studio → Project Settings → Authentication → Allow Auth Providers → GitHub."
step "Sign In / Providers → GitHub → Enabled ON"
step "Paste the Client ID, then the Client Secret you generated in Stage 3 → Save"
step "Site URL: ${ORIGIN}"
step "Redirect URLs — exactly these three lines, one per Add:"
note "  ${ORIGIN}/confirm"
note "  http://localhost:3000/confirm"
note "  http://localhost:3000"
note "A single '*' stops at '/' — it cannot reach /confirm, so each path is listed."
note "Never 'supabase config push': it writes hosted config from supabase/config.toml."
pause "Providers saved, Site URL set, Redirect URLs listed?"
if confirm "Saved?"; then
  publishable=$(_existing NUXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY || true)
  if [[ -n "$publishable" ]]; then
    say "Verifying with the publishable key (a public key; it is why this check is safe here):"
    if curl -s -H "apikey: ${publishable}" "${HOSTED_URL}/auth/v1/settings" \
        | grep -q '"github":[[:space:]]*true'; then
      note "✓ ${HOSTED_URL}/auth/v1/settings reports github enabled"
    else
      warn "GitHub is not reporting enabled yet — re-check the provider, then re-run this stage"
    fi
  else
    SKIPPED+=("Provider verification (NUXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY not in $ENV_FILE)")
  fi
fi

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Hosted schema, read-only"
say "Three reads, no writes. Hosted history is append-only: nothing queued, and"
say "nothing to push (the baseline landed in #25, the grant repair in 20261103000000)."
say "From the repo root (login is read from ~/.config/supabase, so run these):"
step "pnpm exec supabase migration list --linked"
note "expect exactly: ${EXPECTED_MIGRATIONS}, with no local-only row"
step "pnpm exec supabase db advisors --linked --type security"
note "expect the three definer advisories suppressed in Studio → Database → Advisor rules"
note "(buy_basket, join_household, preview_invitation — docs/agents/advisors.md is the register)"
step "pnpm exec supabase db lint --linked --fail-on=error"
note "expect clean; a new advisory is a new decision, not a warning to ignore"
pause "All three reads done?"
if ! confirm "migration list matched and lint came back clean?"; then
  warn "Stop. Read the output before touching production: docs/agents/advisors.md"
fi

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Deploy secrets (the deploy box, the CI's SSH user)"
say "GitHub Actions rsyncs a built .output to the box over SSH. So the box needs"
say "a human-owned SSH target, and the CI needs a key for it. A deploy key ON the"
say "repo is out: the VPS is not a git remote. Nothing here is read from the repo."
ask SSH_HOST "SSH host for the deploy (usually ${ORIGIN#https://})"
ask SSH_USER "SSH user the deploy logs in as (unprivileged)"
ask APP_ROOT "Release root on the box (e.g. /opt/kinetic-lists)"
ask RUNTIME_PORT "Port Nitro listens on behind nginx (e.g. 3000)"
set_var SSH_HOST "$SSH_HOST"
set_var SSH_USER "$SSH_USER"
set_var APP_ROOT "$APP_ROOT"
set_var RUNTIME_PORT "$RUNTIME_PORT"
if confirm "Generate a dedicated deploy key pair under ${KEY_DIR}/ (private key goes to gh secrets)?"; then
  mkdir -p "$KEY_DIR" && chmod 700 "$KEY_DIR"
  if ! grep -qx "${KEY_DIR}/" .gitignore 2>/dev/null; then
    printf '%s/\n' "$KEY_DIR" >> .gitignore
    note "added ${KEY_DIR}/ to .gitignore"
  fi
  ssh-keygen -t ed25519 -a 100 -N "" -C "kinetic-lists-deploy" -f "${KEY_DIR}/deploy_key"
  set_secret SSH_PRIVATE_KEY "$(cat "${KEY_DIR}/deploy_key")"
  say "Public key — you install this on the box in the next stage:"
  note "  $(cat "${KEY_DIR}/deploy_key.pub")"
fi
say "The CI needs the host key too: rsync against a host with no known_hosts entry"
say "stops at the fingerprint prompt, which a CI runner cannot answer. On the box:"
say "   ssh-keyscan -t ed25519,ecdsa,rsa ${SSH_HOST:-host}"
say "Paste the whole block back here (it is public, and it is what the deploy trusts):"
ask_secret SSH_KNOWN_HOSTS "ssh-keyscan output for ${SSH_HOST:-the box}"
set_secret SSH_KNOWN_HOSTS "$SSH_KNOWN_HOSTS"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "The box, once, as root (you run these; the wizard only prints them)"
say "Paste one block at a time. nginx + certbot are already on this box; a cert"
say "for ${ORIGIN#https://} is assumed, and nginx fronted Nitro with WebSocket upgrade"
say "for Realtime (the WS path on a non-Vercel host is #9's last unverified fact)."
say ""
note "1) the deploy user, its key, and the release root:"
say "   useradd -r -m -s /usr/sbin/nologin ${SSH_USER} 2>/dev/null || true"
say "   install -d -o ${SSH_USER} -g ${SSH_USER} -m 750 ${APP_ROOT}/{releases,shared}"
say "   install -d -o root -g root -m 755 /home/${SSH_USER}/.ssh"
say "   printf '%s\n' '<the public key from Stage 6>' >> /home/${SSH_USER}/.ssh/authorized_keys"
say "   chown ${SSH_USER}: ${SSH_USER}/.ssh/authorized_keys && chmod 600 /home/${SSH_USER}/.ssh/authorized_keys"
note "2) the runtime environment (Nitro reads NO .env at runtime — this file is the source):"
say "   install -d -o root -g ${SSH_USER} -m 750 /etc/kinetic-lists"
say "   printf '%s\n' 'HOST=127.0.0.1' 'PORT=${RUNTIME_PORT}' \\
     'NUXT_PUBLIC_SUPABASE_URL=${HOSTED_URL}' 'NUXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=<publishable key>' \\
     'NUXT_PUBLIC_GITHUB_CLIENT_ID=<client id from Stage 3>' > /etc/kinetic-lists/env"
say "   chown root:${SSH_USER} /etc/kinetic-lists/env && chmod 640 /etc/kinetic-lists/env"
note "3) the service, env-first and self-restarting:"
say "   printf '%s\n' '[Unit]' 'Description=Kinetic Lists (Nuxt Nitro)' 'After=network.target' \\
     '[Service]' 'Type=simple' 'User=${SSH_USER}' 'Group=${SSH_USER}' 'WorkingDirectory=${APP_ROOT}/current' \\
     'ExecStart=/usr/bin/env node .output/server/index.mjs' 'EnvironmentFile=/etc/kinetic-lists/env' \\
     'Restart=always' 'RestartSec=2' 'TimeoutStopSec=30' 'KillSignal=SIGTERM' \\
     'StandardOutput=journal' 'StandardError=journal' 'SyslogIdentifier=kinetic-lists' \\
     '[Install]' 'WantedBy=multi-user.target' > /etc/systemd/system/kinetic-lists.service && systemctl daemon-reload"
note "4) nginx fronting it (WebSocket upgrade for Realtime; /confirm is never cached):"
say "   proxy_pass http://127.0.0.1:${RUNTIME_PORT};"
say "   proxy_http_version 1.1; proxy_set_header Upgrade \$http_upgrade; proxy_set_header Connection \"upgrade\";"
say "   proxy_set_header Host \$host; proxy_set_header X-Forwarded-Proto \$scheme; proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;"
say "   location = /confirm { proxy_cache_bypass 1; add_header Cache-Control \"no-store\"; }"
note "5) enable it: systemctl enable --now kinetic-lists && systemctl status kinetic-lists --no-pager"
say ""
warn "Node gate, on the box (the wizard installs nothing): node -v must be ≥ 20.19.1;"
warn "pnpm -v is 10.20.0 to match pnpm-lock.yaml; nginx -t must pass; certbot certificates lists the cert."
if confirm "Service active on ${APP_ROOT}/current and nginx -t clean?"; then
  note "box is ready for the first deploy"
else
  warn "Fix the box first — nothing downstream works without a running service"
fi

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "First deploy, and the sign-in it must survive"
if [[ ! -f .github/workflows/deploy.yml ]]; then
  warn "There is no deploy job in this repo yet: .github/workflows/deploy.yml is #27's"
  warn "deliverable, and this stage verifies a job that must already exist. Stop here,"
  warn "land #27, and re-run. The mint contract is in docs/runbooks/supabase-vps-setup.md"
  warn "(secrets: SSH_PRIVATE_KEY · vars: SSH_HOST, SSH_USER, APP_ROOT, RUNTIME_PORT)."
  finish "Kinetic Lists · hosted Supabase + VPS setup (stopped before deploy)"
  exit 0
fi
say "GitHub Actions rsyncs a built .output to the box over SSH, flips the 'current'"
say "on one box, and the job rsyncs with --delete into a dated release directory."
step "gh workflow run deploy.yml --ref master"
step "gh run list --workflow deploy.yml --limit 3   then: gh run watch <id>"
step "curl -sSf -o /dev/null -w '%{http_code}\\n' ${ORIGIN}/confirm   (expect 200)"
step "Browser: ${ORIGIN}/login → Continue with GitHub → GitHub authorises → /confirm → /app"
note "That round trip is the reason the Redirect URLs are exact; a miss lands on /confirm"
note "with an error in the URL hash, and a PKCE cookie is a one-shot — no retry."
step "Prove the sign-up seed (ADR-0019) on hosted, one statement:"
say "   pnpm exec supabase db query --linked \"select h.name, m.user_name from public.households h join public.household_members m on m.household_id = h.id order by 1 asc\""
note "expect a row naming 'My Household' and the new Member's name — a sign-up with no"
note "Household means the trigger is not on hosted, and every sign-up is unusable."
if confirm "Signed in on ${ORIGIN} AND a Household row appeared?"; then
  note "deploy proven; the app is live with the sign-up seed firing on hosted"
else
  warn "Open the run log and Studio side by side: the deploy, the session, the trigger."
fi

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "Record it"
say "The facts of this run are yours to keep. Paste this block into"
say "docs/runbooks/supabase-vps-setup.md under 'Recorded run', and commit:"
say ""
note "  origin: ${ORIGIN}"
note "  callback: ${CALLBACK}"
note "  redirect urls: ${ORIGIN}/confirm, http://localhost:3000/confirm, http://localhost:3000"
note "  github oauth client id: ${GITHUB_OAUTH_CLIENT_ID:-（recorded in .env）}"
note "  ssh host/user: ${SSH_HOST:-?} / ${SSH_USER:-?}"
note "  app root: ${APP_ROOT:-?} · nitro port: ${RUNTIME_PORT:-?}"
note "  service: kinetic-lists.service · env file: /etc/kinetic-lists/env (0640 root:${SSH_USER:-user})"
note "  dev fixture email: ${DEV_LOGIN_EMAIL:-?} (local part hashed; password stays out of git)"
note "  deploy key: deploy key (generated under ${KEY_DIR}/)"
note "  deploy: .github/workflows/deploy.yml · secrets: SSH_PRIVATE_KEY · vars: SSH_HOST, SSH_USER, APP_ROOT, RUNTIME_PORT"
note "  measured: ${EXPECTED_MIGRATIONS} applied on hosted and local (2026-11-02)"
say ""
warn "Rotating the OAuth Client Secret is the one step v1 has no answer for (#9's"
warn "unverified list): regenerate on GitHub, paste into Studio, restart nothing."

